const finishSimulationJob = `-- name: FinishSimulationJob :one
UPDATE simulation_jobs
SET status = $1,
    progress_pct = CASE WHEN $1 = 'succeeded' THEN 100 ELSE GREATEST(progress_pct, $2) END,
    replications_done = CASE
        WHEN $1 = 'succeeded' THEN replications_total
        ELSE GREATEST(replications_done, $3)
    END,
    error_text = $4,
    finished_at = now(),
    heartbeat_at = now(),
    updated_at = now()
WHERE id = $5 AND status = 'running'
RETURNING id, project_id, run_id, status, progress_pct, attempt, error_text, created_at, updated_at, canceled_at, user_id, config, max_attempts, replications_total, replications_done, started_at, finished_at, heartbeat_at
`

