const purgeExpiredProjects = `-- name: PurgeExpiredProjects :many
DELETE FROM projects
WHERE id IN (
    SELECT id FROM projects
    WHERE deleted_at < $1::timestamptz
    ORDER BY deleted_at
    LIMIT $2
)
RETURNING id
`

type PurgeExpiredProjectsParams struct {
	Before  pgtype.Timestamptz `json:"before"`
	MaxRows int32              `json:"max_rows"`
}

func (q *Queries) PurgeExpiredProjects(ctx context.Context, arg PurgeExpiredProjectsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, purgeExpiredProjects, arg.Before, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

